import zipfile, xml.etree.ElementTree as E
z=zipfile.ZipFile(\"Counter placement.xlsx\")
n={\"m\":\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"}
s=[\"\".join(i.itertext()) for i in E.fromstring(z.read(\"xl/sharedStrings.xml\"))]
for name in (\"sheet1\",\"sheet2\"):
 print(name)
 for row in E.fromstring(z.read(\"xl/worksheets/\"+name+\".xml\")).findall(\".//m:row\",n):
  out=[]
  for c in row:
   v=c.findtext(\"m:v\",namespaces=n); f=c.findtext(\"m:f\",namespaces=n)
   if f: v=\"=\"+f+\" [\"+str(v)+\"]\"
   elif v is not None and c.get(\"t\")==\"s\": v=s[int(v)]
   if v is not None: out.append(c.get(\"r\")+\" \"+v)
  print(\" | \".join(out))
'"
